console.log('[Extract Slot Query Params] EXECUTION START - Input:', JSON.stringify($input.item.json.body, null, 2));

function parseDate(inputDateString) {
  if (!inputDateString) {
    const now = new Date();
    return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())).toISOString().split('T')[0];
  }
  const cleanedInput = String(inputDateString).toLowerCase().trim().replace(/(?<=\d)(st|nd|rd|th)\b/g, '');
  const now = new Date();
  const today = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));

  if (cleanedInput === 'today') return today.toISOString().split('T')[0];
  if (cleanedInput === 'tomorrow') {
    const tomorrow = new Date(today); tomorrow.setUTCDate(today.getUTCDate() + 1); return tomorrow.toISOString().split('T')[0];
  }
  const nextDayMatch = cleanedInput.match(/^next (\w+)/);
  if (nextDayMatch) {
    const daysOfWeek = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
    const targetDayName = nextDayMatch[1];
    let targetDayIndex = daysOfWeek.findIndex(day => day.startsWith(targetDayName.substring(0,3)));
    if (targetDayIndex !== -1) {
      let diff = targetDayIndex - today.getUTCDay(); if (diff <= 0) diff += 7;
      const nextDate = new Date(today); nextDate.setUTCDate(today.getUTCDate() + diff); return nextDate.toISOString().split('T')[0];
    }
  }
  const daysLaterMatch = cleanedInput.match(/^in (\d+) days?/);
  if (daysLaterMatch) {
    const days = parseInt(daysLaterMatch[1], 10);
    const futureDate = new Date(today); futureDate.setUTCDate(today.getUTCDate() + days); return futureDate.toISOString().split('T')[0];
  }
  let dateToParse = cleanedInput;
  if (/^((\d{1,2})[\s\-\/](\w+)|(\w+)[\s\-\/](\d{1,2}))$/.test(cleanedInput) && !/\d{4}/.test(cleanedInput)) {
      dateToParse = `${cleanedInput} ${now.getUTCFullYear()}`;
  }
  let parsedJSDate = new Date(dateToParse);
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateToParse)) {
      const parts = dateToParse.split('-');
      parsedJSDate = new Date(Date.UTC(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2])));
  } else if (dateToParse.length === 2 && !isNaN(parseInt(dateToParse))) {
      const dayOfMonth = parseInt(dateToParse, 10);
      let targetMonth = today.getUTCMonth();
      let targetYear = today.getUTCFullYear();
      if (dayOfMonth < today.getUTCDate()) {
          targetMonth += 1;
          if (targetMonth > 11) { targetMonth = 0; targetYear +=1; }
      }
      parsedJSDate = new Date(Date.UTC(targetYear, targetMonth, dayOfMonth));
  }

  if (!isNaN(parsedJSDate.getTime())) {
    return new Date(Date.UTC(parsedJSDate.getFullYear(), parsedJSDate.getMonth(), parsedJSDate.getDate())).toISOString().split('T')[0];
  }
  console.warn('[Extract Slot Query Params] [parseDate] Failed for input: "' + inputDateString + '". Returning PARSE_ERROR_FLAG.');
  return 'PARSE_ERROR_FLAG';
}

const toolCall = $input.item.json.body.message.toolCalls && $input.item.json.body.message.toolCalls[0];
const argsString = toolCall?.function?.arguments || '{}';
let parsedArgs;
try {
  parsedArgs = typeof argsString === 'string' ? JSON.parse(argsString) : argsString;
} catch (e) {
  console.error('[Extract Slot Query Params] Error parsing arguments: ', e, "Input args:", argsString);
  parsedArgs = {};
}
console.log('[Extract Slot Query Params] Parsed Arguments (parsedArgs):', JSON.stringify(parsedArgs, null, 2));

const toolCallId = toolCall?.id || 'unknown_tool_call_id_from_Extract_Slot_Query_Params_slots';
const userDateInput = parsedArgs.appointmentDate || 'today'; // This is the 'raw' date from Vapi
const formattedDate = parseDate(userDateInput);

if (formattedDate === 'PARSE_ERROR_FLAG') {
  const errorMessage = `I couldn't understand the date '${userDateInput}'. Please try specifying the date clearly, like 'today', 'tomorrow', 'June tenth', or 'next Monday'.`;
  console.error(`[Extract Slot Query Params] Date parsing failed for input: "${userDateInput}". Message: ${errorMessage}`);
  return {
    toolCallId: toolCallId,
    error: "DATE_PARSE_ERROR",
    errorMessage: errorMessage,
    originalWebhookData: $input.item.json.body
  };
}
console.log(`[Extract Slot Query Params] Original date input: "${userDateInput}", Parsed to YYYY-MM-DD: "${formattedDate}"`);

const hospitalOwnerId = parsedArgs.hospitalOwnerId || 1;
let services = [];
try {
  console.log(`[Extract Slot Query Params] Fetching services for hospitalOwnerId: ${hospitalOwnerId} to match serviceName.`);
  const doctorServicesResponse = await $fetch(`https://api.primumai.eu/api/vapi/available/doctor?hospital_owner_id=${hospitalOwnerId}`);
  if (doctorServicesResponse && doctorServicesResponse.data && Array.isArray(doctorServicesResponse.data.services)) {
    services = doctorServicesResponse.data.services;
    console.log(`[Extract Slot Query Params] Successfully fetched ${services.length} services.`);
    if (services.length > 0) {
        console.log('[Extract Slot Query Params] Fetched Services List (first 5 titles):', JSON.stringify(services.slice(0,5).map(s => s.title), null, 2));
    }
  } else {
    console.warn('[Extract Slot Query Params] Fetched services data is not in expected format or empty. Response:', JSON.stringify(doctorServicesResponse));
  }
} catch (error) {
  console.error(`[Extract Slot Query Params] Failed to fetch services: ${error.message}`, error.stack);
}

let serviceId;
const serviceNameFromArgs = parsedArgs.serviceName?.trim();
const serviceIdFromArgs = parsedArgs.serviceId; // Vapi might send this directly
console.log(`[Extract Slot Query Params] Attempting to determine Service ID. From args: serviceName="${serviceNameFromArgs}", serviceId="${serviceIdFromArgs}"`);


if (serviceNameFromArgs && services.length > 0) {
  const matchedService = services.find(service =>
    service && typeof service.title === 'string' &&
    service.title.trim().toLowerCase() === serviceNameFromArgs.toLowerCase()
  );
  if (matchedService) {
    serviceId = matchedService.id;
    console.log(`[Extract Slot Query Params] MATCH FOUND: Service ID ${serviceId} for name: "${serviceNameFromArgs}" (Actual title: "${matchedService.title}")`);
  } else {
    console.warn(`[Extract Slot Query Params] NO MATCH: For service name: "${serviceNameFromArgs}". Available service titles (case-insensitive check against these): ${services.map(s=>`"${s.title.trim().toLowerCase()}"`).join(', ')}`);
  }
} else if (serviceNameFromArgs && services.length === 0) {
    console.warn(`[Extract Slot Query Params] Service name "${serviceNameFromArgs}" was provided, but no services were fetched (or fetch failed). Cannot match.`);
} else if (!serviceNameFromArgs) {
    console.log('[Extract Slot Query Params] No serviceName provided in arguments. Will check for serviceIdFromArgs or default.');
}


if (serviceId === undefined) {
  if (serviceIdFromArgs !== undefined && !isNaN(parseInt(serviceIdFromArgs))) {
    serviceId = parseInt(serviceIdFromArgs);
    console.log(`[Extract Slot Query Params] Using explicit serviceId ${serviceId} from arguments.`);
  } else {
    const defaultServiceId = 9;
    if(serviceNameFromArgs && services.length > 0 && serviceId === undefined) {
        const errorMessage = `I couldn't find the service named '${serviceNameFromArgs}'. Please choose from the available services or try again.`;
        console.error(`[Extract Slot Query Params] CRITICAL FAILURE: Service name "${serviceNameFromArgs}" was provided but NOT MATCHED among ${services.length} fetched services. Returning error to Vapi.`);
        return {
            toolCallId: toolCallId,
            error: "SERVICE_NOT_FOUND",
            errorMessage: errorMessage,
            originalWebhookData: $input.item.json.body
        };
    }
    serviceId = defaultServiceId;
    console.warn(`[Extract Slot Query Params] Service ID defaulting to ${serviceId}. Conditions: serviceNameFromArgs="${serviceNameFromArgs}", serviceIdFromArgs="${serviceIdFromArgs}", services.length=${services.length}.`);
  }
}

console.log(`[Extract Slot Query Params] Final determined serviceId: ${serviceId}`);

return {
  toolCallId,
  originalWebhookData: $input.item.json.body,
  doctorId: parsedArgs.doctorId,
  appointmentDate: formattedDate, 
  originalDateInput: userDateInput, 
  hospitalOwnerId,
  serviceId,
  serviceName: serviceNameFromArgs, 
  gms: parsedArgs.gms === true, 
  timePreference: parsedArgs.timePreference
};
// --- END OF FUNCTION CODE for Extract Slot Query Params ---

